original_review_sources.nested_keys.void:
enum inner:
    empty
    text(data: string)
enum outer:
    empty
    wrapped(data: inner)
func main() -> i32:
    var first = outer.wrapped(inner.text("a" + "b"))
    var second = outer.wrapped(inner.text("ab"))
    var keys: {outer: i32} = {first: 1, second: 2, outer.empty: 3}
    first = outer.empty
    if second != outer.wrapped(inner.text("ab")) or keys.count != 2 or keys[second] != 2 or keys[first] != 3:
        return 1
    return 0

